export async function setLiveProxyTls(
  db: Db, userId: string, clientNumber: string, expected: { host: string | null; port: number | null }, tls: ProxyTlsFields,
): Promise<boolean> {
  const res = await db.query(
    `update public.member_playlist
        set proxy_tls_host = $3, proxy_tls_port = $4, proxy_tls_addr = $5, updated_at = now()
      where user_id = $1 and client_number = $2 and proxy_enabled
        and proxy_host is not distinct from $6::text and proxy_port is not distinct from $7::integer
        and (proxy_tls_host, proxy_tls_port, proxy_tls_addr) is distinct from ($3::text, $4::integer, $5::text)`,
    [userId, clientNumber, tls?.host ?? null, tls?.port ?? null, tls?.addr ?? null, expected.host, expected.port],
  );
  return (res.rowCount ?? 0) > 0;
}
